export function useEmployeesByOrganizationIds(organizationIds: string[], enabled = true) {
  return useQuery({
    queryKey: ['employees-by-organization-ids', JSON.stringify(organizationIds)],
    queryFn: async () => {
      if (!organizationIds || organizationIds.length === 0) return [];
      const responses = await Promise.all(
        organizationIds.map((orgId) => employeeService.getByOrganizationId(orgId)),
      );
      const allEmps: IEmployee[] = [];
      const seenIds = new Set<string>();
      for (const emps of responses) {
        if (Array.isArray(emps)) {
          for (const emp of emps) {
            if (emp?.id && !seenIds.has(emp.id)) {
              seenIds.add(emp.id);
              allEmps.push(emp);
            }
          }
        }
      }
      return allEmps;
    },
    staleTime: DEFAULT_STALE_TIME,
    enabled: enabled && organizationIds.length > 0,
  });
}
